    choices: [
      { key: 'A', text: '複合操作時には、複数のアクチュエータへ同時に圧油を配分する必要があり、負荷の異なるアクチュエータ間で流量の奪い合いが生じやすい。', explanation: '適当。複合操作時の流量配分上の課題である。' },
      { key: 'B', text: 'フロー合流・分流機構や優先弁等を用いることで、複合操作時にも各アクチュエータへ適切に流量を配分し、操作性を確保する工夫がなされている。', explanation: '適当。複合操作の油圧回路設計上の工夫である。' },
      { key: 'C', text: '複数の油圧ポンプを備えた機種では、各ポンプからの吐出油を作業内容に応じて合流・分割させる回路構成が採られることがある。', explanation: '適当。複数ポンプ方式による複合操作対応である。' },
      { key: 'D', text: '油圧ショベルは構造上、複数のアクチュエータを同時に作動させることが一切できず、常に一つの動作のみを単独で行う設計となっている。', explanation: '不適当。油圧ショベルは、掘削・旋回・走行等の複数動作を同時に行う「複合操作」が可能であり、これは油圧ショベルの重要な作業性能の一つである。フロー合流・分流機構等はまさにこの複合操作を成立させるための工夫であり、「同時作動が一切できない」とする記述は基本的な機能を否定しており誤り。' },
    ],
    correctKey: 'D',
    explanation: '油圧ショベルは、ブーム上げと旋回、アーム掘削と旋回、走行と作業装置の操作といった複数動作を同時に行う複合操作が日常的に求められる。ただし複数のアクチュエータへ同時に圧油を送ると、負荷の小さい側へ油が流れやすく、負荷の大きい側が動かないという流量の奪い合いが起きる。このため二つのポンプの吐出油を作業内容に応じて合流や分流させる回路、旋回や走行に流量を優先配分する優先弁、負荷圧に依存せず配分する方式などが用いられ、操作性が確保されている。\n【図解】複合操作を成立させる工夫\n　課題｜内容｜対策\n　流量の奪い合い｜負荷の小さい側へ油が流れる｜優先弁による配分\n　同時作動の要求｜掘削と旋回、走行と作業｜合流分流回路の採用\n　操作性の確保｜負荷変動によらない流量配分｜圧力補償や優先制御\n　⇒ 複合操作は油圧ショベルの重要な作業性能である\n　⚠ 複数のアクチュエータを同時に動かせないという記述は誤り',
