    question: '建設機械の走行用油圧モータに設けられる2速切替機構に関する記述として、最も不適当なものはどれか。',
    choices: [
      { key: 'A', text: '低速側は、モータの押しのけ容積（容量）を大きくすることで、速度は遅いが大きな駆動トルクが得られる設定である。', explanation: '適当。低速側の特性として妥当である。' },
      { key: 'B', text: '高速側は、モータの押しのけ容積を小さくすることで、駆動トルクは小さくなるが、高速走行が可能となる設定である。', explanation: '適当。高速側の特性として妥当である。' },
      { key: 'C', text: '不整地や登坂等、大きな牽引力を要する場面では低速側、平坦な場所での移動等では高速側を選択することが多い。', explanation: '適当。2速切替の使い分けの考え方として妥当である。' },
      { key: 'D', text: '2速切替機構を備えた走行用油圧モータは、速度とトルクが常に同時に最大となる設定を維持できる。', explanation: '不適当。油圧モータの出力特性上、速度（回転数）とトルクは押しのけ容積の変化に対してトレードオフの関係にあり、容積を大きくすれば低速・高トルクに、小さくすれば高速・低トルクになる。「速度とトルクが常に同時に最大となる」という記述は、このトレードオフの関係に反しており誤り。' },
    ],
    correctKey: 'D',
    explanation: '走行用油圧モータの2速切替機構は、モータの押しのけ容積を変えることで速度とトルクを切り替える仕組みである。同じ流量と圧力の下では、押しのけ容積を大きくすると1回転あたりに多くの油が要るため回転数は下がるが、受圧面積が増えてトルクは大きくなる。逆に容積を小さくすれば高速で低トルクになる。この関係はトレードオフであり、両方を同時に最大にすることはできない。不整地や登坂など大きな牽引力が要る場面では低速側、平坦地の移動では高速側を選ぶ。\n【図解】押しのけ容積と走行特性\n　設定｜押しのけ容積｜特性\n　低速側｜大きくする｜低速だが大きな駆動トルク\n　高速側｜小さくする｜高速だがトルクは小さい\n　使い分け｜地形と必要な牽引力による｜登坂は低速、平坦は高速\n　⇒ 速度とトルクはトレードオフの関係にある\n　⚠ 速度とトルクが常に同時に最大となるという記述は誤り',
