    explanation: '振幅・振動数は締固め対象・層厚に応じて切替可能な機種があり、条件により使い分けられる。\n【図解】振幅・振動数の使い分け\n　高振幅・低振動数★：衝撃力大→厚い層の締固めに適する\n　低振幅・高振動数★：衝撃力小・頻度多→薄層仕上げ・舗装仕上げに適する\n　×「常に固定値で調整不可」は誤り\n　→対象条件に応じた切替が実務上重要',
