    question: 'コンバインドローラ（鉄輪＋タイヤの複合ローラ）に関する記述として、最も不適当なものはどれか。',
    choices: [
      { key: 'A', text: 'コンバインドローラは、片側に振動可能な鉄輪、もう片側にゴムタイヤを配置した複合構造のローラである。', explanation: '適当。コンバインドローラの基本的な構造である。' },
      { key: 'B', text: '鉄輪側の振動による締固め効果と、タイヤ側のニーディング（練り込み）作用による締固め効果を1台で得られる利点がある。', explanation: '適当。コンバインドローラの複合的な締固め効果である。' },
      { key: 'C', text: 'アスファルト舗装の中間転圧や仕上げ転圧等、複数の締固め機能を1台でまかないたい場面で用いられることがある。', explanation: '適当。コンバインドローラの代表的な用途である。' },
      { key: 'D', text: 'コンバインドローラは前後輪ともに同一のゴムタイヤのみで構成される機械であり、鉄輪は一切装備されていない。', explanation: '不適当。コンバインドローラの最大の特徴は「鉄輪（多くは振動機構付き）とゴムタイヤを組み合わせた」複合構造にある点であり、前後輪とも同一のゴムタイヤのみで構成される機械（タイヤローラ）とは異なる。「鉄輪は一切装備されていない」とする記述は誤り。' },
    ],
    correctKey: 'D',
    explanation: 'コンバインドローラは、片側に振動機構をもつ鉄輪、もう片側にゴムタイヤを配置した複合構造のローラである。鉄輪の振動で密度を高めつつ、タイヤのもみ込み作用で表面の骨材を落ち着かせて緻密に仕上げられるため、1台で二次転圧から仕上げ転圧までまかなえる。機械の持込み台数を減らせるので、施工幅の小さい現場や補修工事で重宝する。前後輪とも同じゴムタイヤで構成されるのはタイヤローラであり、鉄輪を備えないという説明はコンバインドローラの定義に反する。\n【図解】ローラの輪の組合せ\n　機械｜輪の構成｜得られる効果\n　振動ローラ｜鉄輪に起振装置を備える｜振動による深部までの締固め\n　タイヤローラ｜ゴムタイヤのみ｜もみ込み作用と接地圧の調整\n　コンバインドローラ｜振動鉄輪とゴムタイヤ｜両方の効果を1台で得る\n　⇒ 持込み台数を減らせるため小規模な現場に向く\n　⚠ ゴムタイヤのみで鉄輪を装備しないという記述は誤り',
