    explanation: '全周回転掘削機は、先端にビットを備えたケーシングチューブを油圧で全周回転または揺動させながら地中へ圧入し、その内部の土砂をハンマグラブでつかみ上げて排土する機械で、オールケーシング工法に用いられる。ケーシングが常に孔壁を保持するので、安定液を用いなくても崩壊を防ぐことができ、泥水の処理も不要である。玉石まじりや硬い地盤、既設杭の撤去にも適用でき、鉛直精度も確保しやすい。ケーシングチューブを使わない素掘りの機械ではない。\n【図解】オールケーシング工法の特徴\n　項目｜内容｜利点\n　孔壁保護｜ケーシングチューブで全長を保持｜安定液が不要になる\n　掘削と排土｜ハンマグラブでつかみ上げる｜玉石まじりにも対応\n　精度｜チューブが案内となる｜鉛直精度を確保しやすい\n　⇒ 既設杭の撤去などにも適用される\n　⚠ ケーシングを使わず素掘りで掘削するという記述は誤り',
