    question: '共振（無共振）バイブロハンマに関する記述として、最も不適当なものはどれか。',
    choices: [
      { key: 'A', text: 'バイブロハンマは、偏心錘（偏心ウエイト）を回転させることで振動を発生させ、鋼矢板や杭を地中に貫入・引抜きする機械である。', explanation: '適当。バイブロハンマの基本的な作動原理である。' },
      { key: 'B', text: '無共振（低振動）型バイブロハンマは、起振開始時と停止時に、周辺への振動が大きくなる共振周波数帯を高速で通過させることで、周辺への振動影響を低減する仕組みを持つ。', explanation: '適当。無共振型バイブロハンマの基本原理である。' },
      { key: 'C', text: '偏心モーメントを可変とすることで、地盤条件や対象物に応じて起振力を調整できる機種がある。', explanation: '適当。可変偏心モーメント式の特徴である。' },
      { key: 'D', text: '無共振型バイブロハンマは、あえて共振周波数帯で長時間運転することで、周辺への振動影響を意図的に増大させる装置である。', explanation: '不適当。無共振（低振動）型バイブロハンマは、逆に「共振周波数帯を高速で通過させる（滞留させない）」ことで、周辺構造物・地盤への振動影響を「低減」することを目的とした装置であり、共振帯で意図的に長時間運転して振動を増大させる装置ではない。記述は目的を逆に説明している。' },
    ],
    correctKey: 'D',
    explanation: 'バイブロハンマは偏心錘を回して起振し、その振動で鋼矢板や杭を貫入したり引き抜いたりする機械である。問題は起動時と停止時で、回転数が上下する過程で周辺地盤や構造物の固有振動数と一致する共振周波数帯を通過し、そこで振動が大きく増幅されることである。無共振型は、偏心モーメントをゼロにした状態で定格回転まで上げてから偏心モーメントを与える方式などにより共振帯を実質的に回避し、周辺への振動影響を抑える。共振帯で意図的に運転する装置ではない。\n【図解】無共振型バイブロハンマの考え方\n　場面｜通常型｜無共振型\n　起動時と停止時｜共振帯を通過し振動が増幅｜共振帯を実質的に回避\n　起振力｜固定の偏心モーメント｜可変として調整できる\n　周辺への影響｜近接構造物へ振動が伝わる｜振動の影響を低減できる\n　⇒ 地盤条件や対象物に応じて起振力を調整できる機種もある\n　⚠ 共振帯で長時間運転し振動を増大させる装置という記述は逆',
