    explanation: 'MTBFは値が大きいほど信頼性が高いことを示す指標であり、小さいほど信頼性が高いという説明は逆で誤り。\n【図解】MTBF・MTTRの意味\n　MTBF★（平均故障間隔）：大きいほど信頼性が高い\n　MTTR★（平均修復時間）：小さいほど保全性が高い\n　アベイラビリティ＝MTBF／（MTBF＋MTTR）\n　×「MTBFが小さいほど信頼性が高い」は逆で誤り',
