    correctKey: 'D',
    explanation: '低騒音型建設機械の指定制度は、国が定めた騒音基準を満たす機種を指定する制度であり、公共工事の仕様書などで使用が促進される、いわば機械そのものを対象とした発生源対策である。これに対して騒音規制法は、都道府県知事等が指定する地域内の特定建設作業について、敷地境界における騒音の規制基準、作業時間帯、作業期間、市町村長への届出を定める法律で、作業を対象とした規制である。両者は根拠も所管も規制の枠組みも異なる別々の制度であり、指定機械の使用は規制基準の遵守に資する手段となる。\n【図解】二つの制度の位置づけ\n　制度｜対象｜内容\n　低騒音型指定制度｜建設機械そのもの｜騒音基準を満たす機種を指定\n　騒音規制法｜特定建設作業｜敷地境界の規制基準と時間帯\n　両者の関係｜指定機械の使用は有効な手段｜規制基準の遵守に資する\n　⇒ 発生源での対策と作業の規制は互いに補完し合う\n　⚠ 両者が同一の法律に基づく単一の制度という記述は誤り',
