    choices: [
      { key: 'A', text: '湿式ディスクブレーキは、ブレーキディスクをオイル中に浸した状態で作動させる方式で、摩擦熱の冷却性に優れ、放熱性が高い傾向がある。', explanation: '適当。湿式ディスクブレーキの基本的な特徴である。' },
      { key: 'B', text: '湿式ディスクブレーキは、密閉構造により泥・水等の異物が侵入しにくく、過酷な使用条件下での耐久性に優れる傾向があり、大型建設機械に採用されることがある。', explanation: '適当。湿式ディスクブレーキの耐久性・密閉性の利点として妥当である。' },
      { key: 'C', text: '乾式ブレーキは、比較的簡易な構造でコストを抑えやすい一方、湿式に比べて放熱性や耐久性の面で劣る場合がある。', explanation: '適当。乾式ブレーキの特徴として妥当である。' },
      { key: 'D', text: '湿式ディスクブレーキと乾式ブレーキは構造・特性が全く同一であり、大型建設機械での採用状況に差異は存在しない。', explanation: '不適当。湿式ディスクブレーキは密閉構造・オイル冷却による高い放熱性・耐久性を持つため、過酷な使用条件が想定される大型建設機械に採用されやすい傾向があるのに対し、乾式ブレーキは比較的簡易な構造でコストを抑えやすいという違いがあり、「構造・特性が全く同一で採用状況に差異はない」とする記述は誤り。' },
    ],
    correctKey: 'D',
    explanation: '建設機械のブレーキには湿式ディスクブレーキと乾式ブレーキがある。湿式はディスクとプレートを油の中に浸した密閉構造で、発生した摩擦熱を油が奪って放熱するため熱容量が大きく、フェードしにくい。密閉されているので泥や水、粉じんが入り込まず、摩擦材の寿命も長い。このため長い下り坂や過酷な条件で使う重ダンプトラックやホイールローダなどの大型機に採用される。乾式は構造が簡易で軽くコストも抑えられるが、放熱性と異物への耐性の面で劣る。\n【図解】ブレーキ方式の比較\n　方式｜構造｜特性\n　湿式ディスクブレーキ｜油中に浸した密閉構造｜放熱性と耐久性に優れる\n　乾式ブレーキ｜大気中で摩擦させる構造｜簡易でコストが低い\n　採用の傾向｜使用条件の厳しさによる｜大型機は湿式が多い\n　⇒ 湿式は泥や水の侵入を受けにくく寿命が長い\n　⚠ 構造も特性も同一で採用状況に差がないという記述は誤り',
    difficulty: 'standard',
